WITH parsed AS (SELECT id, customer_id, coupon_codes, items, ship_to, TRANSFORM(items, item -> item.product_id) AS product_ids, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, FORALL(items, item -> item.qty <= 5) AS all_small_qty FROM carts) SELECT customer_id, COUNT(*) AS event_count, COUNT(*) AS cnt, COUNT(DISTINCT id) AS distinct_ids FROM parsed GROUP BY customer_id ORDER BY event_count NULLS FIRST;
